import { createHash } from "node:crypto";

import { evaluateEvidenceVerifier } from "./evidence-verifier.js";

export type EvidenceVerificationStatus =
  | "completed"
  | "insufficient_evidence"
  | string;

export type CompletionVerdict = "approved" | "insufficient-evidence" | "rejected";

export interface CompletionVerdictScope {
  readonly taskIds: readonly string[];
}

export interface CompletionVerdictRecord {
  readonly taskId: string;
  readonly verdict: CompletionVerdict;
  readonly evidenceDigest: string;
  readonly findingCodes: readonly string[];
  readonly priorStatus: string;
  readonly grantsPublish: false;
  readonly grantsProductLock: false;
}

export interface CompletionVerdictInput {
  readonly scope: CompletionVerdictScope;
  readonly taskId: string;
  readonly evidence: unknown;
  readonly priorStatus: string;
}

export interface CompletionVerdictDecision {
  readonly outcome: CompletionVerdict | "out-of-scope";
  readonly record: CompletionVerdictRecord | null;
  readonly transition: { readonly from: string; readonly to: "done" } | null;
}

export interface CompletionVerdictRevocation {
  readonly from: "done";
  readonly to: string;
}

interface EvidenceVerifierResult {
  readonly status?: EvidenceVerificationStatus;
  readonly evidenceStatus?: EvidenceVerificationStatus;
  readonly evidenceDigest?: string;
  readonly digest?: string;
  readonly findingCodes?: readonly string[];
  readonly findings?: readonly { readonly code?: string }[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function stableSerialize(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(stableSerialize).join(",")}]`;
  }
  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, item]) => item !== undefined)
    .sort(([left], [right]) => left.localeCompare(right));
  return `{${entries
    .map(([key, item]) => `${JSON.stringify(key)}:${stableSerialize(item)}`)
    .join(",")}}`;
}

function digestEvidence(evidence: unknown): string {
  return createHash("sha256").update(stableSerialize(evidence), "utf8").digest("hex");
}

function readVerifierResult(result: unknown): EvidenceVerifierResult {
  if (!isRecord(result)) {
    return {};
  }
  const nested = isRecord(result.evaluation) ? result.evaluation : undefined;
  return {
    status:
      typeof result.status === "string"
        ? result.status
        : typeof result.evidenceStatus === "string"
          ? result.evidenceStatus
          : typeof nested?.status === "string"
            ? nested.status
            : undefined,
    evidenceDigest:
      typeof result.evidenceDigest === "string"
        ? result.evidenceDigest
        : typeof result.digest === "string"
          ? result.digest
          : typeof nested?.evidenceDigest === "string"
            ? nested.evidenceDigest
            : undefined,
    findingCodes: Array.isArray(result.findingCodes)
      ? result.findingCodes.filter((code): code is string => typeof code === "string")
      : undefined,
    findings: Array.isArray(result.findings)
      ? result.findings.filter((finding): finding is { readonly code?: string } => isRecord(finding))
      : undefined,
  };
}

function findingCodes(result: EvidenceVerifierResult): readonly string[] {
  if (result.findingCodes) {
    return [...result.findingCodes];
  }
  if (result.findings) {
    return result.findings
      .map((finding) => finding.code)
      .filter((code): code is string => typeof code === "string");
  }
  return [];
}

function verdictForStatus(status: EvidenceVerificationStatus | undefined): CompletionVerdict {
  if (status === "completed") {
    return "approved";
  }
  if (status === "insufficient_evidence") {
    return "insufficient-evidence";
  }
  return "rejected";
}

/**
 * Produces a bounded, digest-only completion decision. This function deliberately
 * delegates verification to the existing evidence verifier and never mutates
 * the supplied evidence, scope, or prior status.
 */
export function createCompletionVerdict(input: CompletionVerdictInput): CompletionVerdictDecision {
  if (!input.scope.taskIds.includes(input.taskId)) {
    return {
      outcome: "out-of-scope",
      record: null,
      transition: null,
    };
  }

  const evaluated = readVerifierResult(evaluateEvidenceVerifier(input.evidence as never));
  const verdict = verdictForStatus(evaluated.status);
  const record: CompletionVerdictRecord = {
    taskId: input.taskId,
    verdict,
    evidenceDigest: evaluated.evidenceDigest ?? digestEvidence(input.evidence),
    findingCodes: findingCodes(evaluated),
    priorStatus: input.priorStatus,
    grantsPublish: false,
    grantsProductLock: false,
  };

  return {
    outcome: verdict,
    record,
    transition: verdict === "approved" ? { from: input.priorStatus, to: "done" } : null,
  };
}

/** Revokes only an approved completion and restores its recorded prior status. */
export function revokeCompletionVerdict(
  record: CompletionVerdictRecord,
): CompletionVerdictRevocation | null {
  if (record.verdict !== "approved") {
    return null;
  }
  return { from: "done", to: record.priorStatus };
}

